# %% ../../nbs/handlers/ospar.ipynb #a2bf13a1
def load_data(
        fname_in # Path or URL to the folder of raw OSPAR csv files
        ):
    "Load OSPAR data; returns dict of DataFrames keyed by sample type"
    res = {}
    for prefix,smp_type in default_smp_types.items():
        fname = f'{prefix} data.csv'
        if fname_in.startswith('http'): fname = fname.replace(' ', '%20')
        res[smp_type] = pd.read_csv(f'{fname_in}/{fname}').rename(str.lower, axis='columns')
    return res


