class ParseTimeCB(PerGroupCB):
    "Parse OSPAR `sampling date` (MM/DD/YY HH:MM:SS) into TIME"
    def each_grp(self, grp, df, tfm):
        df['TIME'] = pd.to_datetime(df['sampling date'], format='%m/%d/%y %H:%M:%S', errors='coerce')

