# %% ../../nbs/handlers/ospar.ipynb #79e69728
class NormalizeUncCB(PerGroupCB):
    "Convert expanded uncertainty (coverage factor k) to standard uncertainty UNC"
    def __init__(self,
                 coi: dict=coi_unc, # {group: uncertainty column}
                 k: float=2, # Coverage factor of the reported uncertainty
                ):
        store_attr()

    def each_grp(self, grp, df, tfm): df['UNC'] = df[self.coi[grp]] / self.k

