lut_units = {
    'bq/l':       (1, 1000), # Bq/L to Bq/m³ (MARIS unit 1)
    'bq/kg f.w.': (5, 1),    # Bq/kg fresh weight, stored as Bq/kgw (MARIS unit 5)
}

# %% ../../nbs/handlers/ospar.ipynb #90b2569b
class RemapUnitCB(PerGroupCB):
    "Set UNIT from the reported unit and convert VALUE and UNC to it (seawater Bq/L to Bq/m³)"
    def __init__(self,
                 lut: dict=lut_units, # {lowercased provider unit: (MARIS unit ID, conversion factor)}
                ):
        store_attr()

    def each_grp(self, grp, df, tfm):
        unit = df['unit'].str.lower().str.strip()
        df['UNIT'] = unit.map({k: v[0] for k, v in self.lut.items()}).fillna(0).astype(int)
        factor = unit.map({k: v[1] for k, v in self.lut.items()}).fillna(1)
        for c in ['VALUE', 'UNC']: df[c] = df[c] * factor

