# %% ../../nbs/handlers/ospar.ipynb #1d6160a4
class RemapDetectionLimitCB(PerGroupCB):
    "Map OSPAR `value type` (`=` / `<`) to MARIS detection-limit codes, treating a missing type with an uncertainty as detected"
    def __init__(self,
                 coi: dict=coi_dl, # {group: {'DL': column holding the value type}}
                 lut: dict=lut_dl, # {value type: MARIS DL code}
                ):
        store_attr()

    def each_grp(self, grp, df, tfm):
        dl = df[self.coi[grp]['DL']].map(self.lut)
        dl[dl.isna() & df['UNC'].notna()] = 1
        df['DL'] = dl.fillna(0).astype(int)

