# %% ../../nbs/handlers/ospar.ipynb #2387b0b7
class EnhanceSpeciesCB(PerGroupCB):
    "Replace SPECIES 0 (not available) with the broad MARIS entry of the record's biological group"
    grps = ['BIOTA']
    def __init__(self,
                 lut: dict=lut_biogroup_species, # {lowercased biological group: MARIS species_id}
                ):
        store_attr()

    def each_grp(self, grp, df, tfm):
        grp_species = df['biological group'].str.strip().str.lower().map(self.lut)
        fill = (df['SPECIES'] == 0) & grp_species.notna()
        df.loc[fill, 'SPECIES'] = grp_species[fill].astype(int)

# %% ../../nbs/handlers/ospar.ipynb #b6448697
class NormalizeBodyPartCB(PerGroupCB):
    "Lowercase and trim `body part` into BODY_PART, resolving plain `whole` to whole animal or whole plant from the biological group"
    grps = ['BIOTA']
    def __init__(self,
                 plant_grps: list=['seaweed', 'seaweeds'], # Lowercased biological groups whose `whole` means whole plant
                ):
        store_attr()

    def each_grp(self, grp, df, tfm):
        bp = df['body part'].str.strip().str.lower()
        whole = bp == 'whole'
        plant = df['biological group'].str.strip().str.lower().isin(self.plant_grps)
        bp[whole & plant] = 'whole plant'
        bp[whole & ~plant] = 'whole animal'
        df['BODY_PART'] = bp

