# %% ../../nbs/handlers/ospar.ipynb #f0bb47c6
def dms_to_dd(
        d: pd.Series, # Degrees
        m: pd.Series, # Minutes
        s: pd.Series, # Seconds; -1 means not recorded
        hemi: pd.Series, # Hemisphere: N, S, E or W
        ) -> pd.Series: # Decimal degrees; NaN when minutes exceed 60
    "Convert OSPAR degree, minute, second and hemisphere columns to signed decimal degrees"
    s = s.where(s != -1, 0)
    neg = hemi.str.strip().isin(['S', 'W']) | (d < 0) | (m < 0) | (s < 0)
    dd = (d.abs() + m.abs() / 60 + s.abs() / 3600).where(m.abs() <= 60)
    return dd.where(~neg, -dd)

# %% ../../nbs/handlers/ospar.ipynb #7da98048
class ParseCoordinatesCB(PerGroupCB):
    "Convert OSPAR degree-minute-second coordinates to decimal LAT and LON, dropping records whose coordinates cannot be interpreted"
    def each_grp(self, grp, df, tfm):
        df['LAT'] = dms_to_dd(df['latd'], df['latm'], df['lats'], df['latdir'])
        df['LON'] = dms_to_dd(df['longd'], df['longm'], df['longs'], df['longdir'])
        tfm.dfs[grp] = df.dropna(subset=['LAT', 'LON'])

# %% ../../nbs/handlers/ospar.ipynb #93ac4bd3
class AddStationCB(PerGroupCB):
    "Copy OSPAR `station id`, trimmed, to MARIS-standard STATION"
    def each_grp(self, grp, df, tfm): df['STATION'] = df['station id'].fillna('').astype(str).str.strip()

# %% ../../nbs/handlers/ospar.ipynb #43bd3463
def get_cbs() -> list:
    "Callbacks, in pipeline order, that turn raw OSPAR data into MARIS-standard DataFrames"
    return [
        RemoveAllNAValuesCB(nan_cols_to_check),
        # Nuclide normalisation and mapping
        LowerStripNameCB(col_src='nuclide', col_dst='NUCLIDE'),
        RemapCB(lut=nuclide_lut, col_remap='NUCLIDE', col_src='NUCLIDE'),
        # Time
        ParseTimeCB(),
        EncodeTimeCB(),
        # Value, uncertainty, unit and detection limit
        SanitizeValueCB(coi_val),
        NormalizeUncCB(),
        RemapUnitCB(),
        RemapDetectionLimitCB(),
        # BIOTA lookups: species, biological group, body part
        LowerStripNameCB(col_src='species', col_dst='SPECIES', grps=['BIOTA']),
        RemapCB(lut=species_lut, col_remap='SPECIES', col_src='SPECIES', grps=['BIOTA']),
        EnhanceSpeciesCB(),
        RemapCB(lut=lut_biogroup, col_remap='BIO_GROUP', col_src='SPECIES', grps=['BIOTA']),
        NormalizeBodyPartCB(),
        RemapCB(lut=body_part_lut, col_remap='BODY_PART', col_src='BODY_PART', grps=['BIOTA']),
        # Depth, coordinates, station
        AddDepthCB(),
        ParseCoordinatesCB(),
        SanitizeLonLatCB(),
        AddStationCB(),
        # Sample identifiers, once all record drops are done
        AddSampleIDCB()
    ]

