# %% ../../nbs/handlers/ospar.ipynb #f0bbfbeb
def get_attrs(
    tfm: Transformer, # Transformer object
    zotero_key: str, # Zotero dataset record key
    kw: list = kw # List of keywords
    ) -> dict: # Global attributes
    "Retrieve all global attributes"
    return GlobAttrsFeeder(tfm.dfs, cbs=[
        BboxCB(),
        DepthRangeCB(),
        TimeRangeCB(),
        ZoteroCB(zotero_key),
        KeyValuePairCB('keywords', ', '.join(kw)),
        KeyValuePairCB('publisher_postprocess_logs', ', '.join(tfm.logs))
        ])()

# %% ../../nbs/handlers/ospar.ipynb #6c48b707
def encode(
    dest: str, # Output file name
    src: str = None, # Path to raw OSPAR data; defaults to `src_dir`
    **kwargs # Additional arguments
    ) -> None:
    "OSPAR radioactive substances monitoring data (seawater and biota)"
    dfs = load_data(src or src_dir)
    # For a quick test file, keep 10 random records per sample type:
    # dfs = {k: v.sample(10, random_state=42) for k, v in dfs.items()}
    tfm = Transformer(dfs, cbs=get_cbs())
    tfm()
    encoder = NetCDFEncoder(tfm.dfs,
                            dest_fname=dest,
                            global_attrs=get_attrs(tfm, zotero_key=zotero_key, kw=kw),
                            verbose=kwargs.get('verbose', False),
                           )
    encoder.encode()

